import{_ as o,o as u,c as q,ag as a}from"./chunks/framework.CukOUUOK.js";const d=JSON.parse('{"title":"感知的切除手术：中国文艺四十年变迁中的权力解剖学","description":"一、问题的提出：谁在书写\\"沉默\\"的前史 讨论公共表达的萎缩，学界惯于从2013年后的制度收紧切入。这是一种诊断上的懒惰。它把症状当作病因，把急性发作当作病程起点。事实上，公共言说能力的丧失，是一个长达…","frontmatter":{"title":"感知的切除手术：中国文艺四十年变迁中的权力解剖学","categories":"权力与制度","tags":["文艺","言论空间","历史"],"description":"一、问题的提出：谁在书写\\"沉默\\"的前史 讨论公共表达的萎缩，学界惯于从2013年后的制度收紧切入。这是一种诊断上的懒惰。它把症状当作病因，把急性发作当作病程起点。事实上，公共言说能力的丧失，是一个长达…","date":"2026-08-28T12:00:00.000Z","series":"莫谈国事","seriesOrder":2},"headers":[],"relativePath":"posts/2026-08-28-the-perception-lobotomy.md","filePath":"posts/2026-08-28-the-perception-lobotomy.md","lastUpdated":1789992750000}'),r={name:"posts/2026-08-28-the-perception-lobotomy.md"};function e(n,t,s,p,h,i){return u(),q("div",null,[...t[0]||(t[0]=[a('<h1 id="感知的切除手术-中国文艺四十年变迁中的权力解剖学" tabindex="-1">感知的切除手术：中国文艺四十年变迁中的权力解剖学 <a class="header-anchor" href="#感知的切除手术-中国文艺四十年变迁中的权力解剖学" aria-label="Permalink to &quot;感知的切除手术：中国文艺四十年变迁中的权力解剖学&quot;">​</a></h1><h2 id="一、问题的提出-谁在书写-沉默-的前史" tabindex="-1">一、问题的提出：谁在书写&quot;沉默&quot;的前史 <a class="header-anchor" href="#一、问题的提出-谁在书写-沉默-的前史" aria-label="Permalink to &quot;一、问题的提出：谁在书写&quot;沉默&quot;的前史&quot;">​</a></h2><p>讨论公共表达的萎缩，学界惯于从2013年后的制度收紧切入。这是一种诊断上的懒惰。它把症状当作病因，把急性发作当作病程起点。事实上，公共言说能力的丧失，是一个长达四十年的慢性器质性病变过程。而这一病变最核心的手术台，不在法院，不在宣传部红头文件上，而在电影院、在电视机前、在每一个被精心投喂的叙事文本之中。</p><p>文艺从来不是政治的附庸或注脚。在当代中国的治理术中，文艺是一种<strong>前置性的感知基础设施</strong>。它先于法律界定何为&quot;可感的&quot;，先于禁令划定何为&quot;可想的&quot;，先于审查内化何为&quot;不必追问的&quot;。理解这一点，是理解一切的前提。</p><p>本文的任务，是对这只&quot;无形之手&quot;进行解剖学意义上的暴露——不是控诉，不是哀叹，而是像外科医生打开胸腔那样，把每一根神经、每一块肌肉、每一个缝合口展示出来。</p><h2 id="二、第一刀-从-伤痕-到-治愈-——命名权的剥夺与回收-1978-1989" tabindex="-1">二、第一刀：从&quot;伤痕&quot;到&quot;治愈&quot;——命名权的剥夺与回收（1978-1989） <a class="header-anchor" href="#二、第一刀-从-伤痕-到-治愈-——命名权的剥夺与回收-1978-1989" aria-label="Permalink to &quot;二、第一刀：从&quot;伤痕&quot;到&quot;治愈&quot;——命名权的剥夺与回收（1978-1989）&quot;">​</a></h2><h3 id="_2-1-短暂的-共名-时刻" tabindex="-1">2.1 短暂的&quot;共名&quot;时刻 <a class="header-anchor" href="#_2-1-短暂的-共名-时刻" aria-label="Permalink to &quot;2.1 短暂的&quot;共名&quot;时刻&quot;">​</a></h3><p>1978至1989年间，中国文艺经历了一个极为特殊的历史窗口。伤痕文学（刘心武《班主任》、卢新华《伤痕》）、反思文学（张贤亮《绿化树》、王蒙《布礼》）、第四代与第五代早期电影（谢晋《芙蓉镇》、陈凯歌《黄土地》、张艺谋《活着》）——这些作品的共同特征并非&quot;批判性&quot;，而是<strong>命名性</strong>。</p><p>它们的功能是：将一种弥漫的、弥散的、无法言说的集体经验，赋予形式、赋予语法、赋予公共可见性。观众在银幕前流泪，不是因为&quot;被感动&quot;，而是因为<strong>被确认</strong>。&quot;原来我经历的苦难不是我的错觉，原来它有一个名字，原来它可以被说出来。&quot;</p><p>这是一种极其危险的力量。因为它意味着，个体经验开始脱离官方叙事的独占解释权，形成独立的公共语义场。</p><h3 id="_2-2-权力的第一次应激反应" tabindex="-1">2.2 权力的第一次应激反应 <a class="header-anchor" href="#_2-2-权力的第一次应激反应" aria-label="Permalink to &quot;2.2 权力的第一次应激反应&quot;">​</a></h3><p>1983年&quot;清除精神污染&quot;运动、1987年反自由化，本质上是对这种&quot;命名权旁落&quot;的应激反应。权力意识到：一旦文艺获得了独立于官方话语的命名能力，它就构成了一个平行的合法性来源。这比任何政治反对派都更致命，因为它不需要组织，不需要纲领，只需要一个故事、一个镜头、一句台词，就能在亿万人心中同时完成&quot;确权&quot;。</p><p>此后的所有文艺管控，无论形式如何变化，其底层逻辑始终未变：<strong>命名权必须垄断。不是禁止你说，而是由我来定义你经历的是什么。</strong></p><h2 id="三、第二刀-市场化作为驯化工具——-去政治化-的政治-1990-2008" tabindex="-1">三、第二刀：市场化作为驯化工具——&quot;去政治化&quot;的政治（1990-2008） <a class="header-anchor" href="#三、第二刀-市场化作为驯化工具——-去政治化-的政治-1990-2008" aria-label="Permalink to &quot;三、第二刀：市场化作为驯化工具——&quot;去政治化&quot;的政治（1990-2008）&quot;">​</a></h2><h3 id="_3-1-一个被严重误读的历史转折" tabindex="-1">3.1 一个被严重误读的历史转折 <a class="header-anchor" href="#_3-1-一个被严重误读的历史转折" aria-label="Permalink to &quot;3.1 一个被严重误读的历史转折&quot;">​</a></h3><p>主流叙事将1992年后文艺的商业化视为&quot;市场化改革的自然结果&quot;。这是一种刻意的去历史化。事实上，文艺市场化从一开始就不是一个经济事件，而是一个<strong>治理技术的升级</strong>。</p><p>1990年代初，决策层面临一个结构性难题：意识形态动员机制已经失效，但直接高压管控成本过高且引发反弹。解决方案是：<strong>用市场替代意识形态，用消费替代参与，用快感替代意义。</strong> 文艺不再需要&quot;为政治服务&quot;，它只需要&quot;不为政治服务&quot;——而实现这一目标的最经济手段，就是让它变成商品。</p><p>资本在这里不是独立的第三方力量。它是被征用的执行者。当利润成为唯一评价标准，&quot;深刻&quot;自动变成风险，&quot;安全&quot;自动变成溢价。创作者不需要被禁止写什么，他只需要面对一个简单的问题：<strong>这个写出来，能过审吗？能卖吗？</strong> 双重过滤之下，自我审查比任何审查官都高效。</p><h3 id="_3-2-冯小刚范式的真正含义" tabindex="-1">3.2 冯小刚范式的真正含义 <a class="header-anchor" href="#_3-2-冯小刚范式的真正含义" aria-label="Permalink to &quot;3.2 冯小刚范式的真正含义&quot;">​</a></h3><p>冯小刚贺岁片的成功常被归因于&quot;市民趣味&quot;。这是表面文章。其深层功能是完成了一次<strong>感知降维</strong>：将公共生活的复杂性压缩为私人情感的悲欢，将结构性矛盾转化为个体命运的巧合，将&quot;我们&quot;的问题缩小为&quot;我&quot;的烦恼。</p><p>《甲方乙方》《没完没了》《大腕》——这些影片的共同结构是：所有冲突最终都在私人领域内消解，所有痛苦最终都被温情覆盖。观众走出电影院时获得的不是&quot;被刺痛后的清醒&quot;，而是&quot;被抚慰后的满足&quot;。</p><p>这不是娱乐。这是<strong>公共痛觉神经的局部麻醉</strong>。每一次笑声，都是一次微型的去政治化手术。</p><h3 id="_3-3-主旋律的转型-从-教育-到-抚慰" tabindex="-1">3.3 主旋律的转型：从&quot;教育&quot;到&quot;抚慰&quot; <a class="header-anchor" href="#_3-3-主旋律的转型-从-教育-到-抚慰" aria-label="Permalink to &quot;3.3 主旋律的转型：从&quot;教育&quot;到&quot;抚慰&quot;&quot;">​</a></h3><p>与此同时，主旋律文艺完成了从&quot;动员型&quot;到&quot;抚慰型&quot;的转型。1990年代前的主旋律（《开国大典》《大决战》）仍试图激发一种集体使命感；而此后，它逐渐退化为一种&quot;一切都在变好&quot;的情绪供给。《生死抉择》《任长霞》《焦裕禄》——这些作品的叙事功能是：<strong>你不需要参与，你不需要追问，你只需要相信有人在替你解决问题。</strong></p><p>这是葛兰西意义上的&quot;文化霸权&quot;最精致的形态：不是强迫你同意，而是让你觉得没有什么需要不同意。</p><h2 id="四、第三刀-安全现实主义——拟态真实的精密制造-2008-2018" tabindex="-1">四、第三刀：安全现实主义——拟态真实的精密制造（2008-2018） <a class="header-anchor" href="#四、第三刀-安全现实主义——拟态真实的精密制造-2008-2018" aria-label="Permalink to &quot;四、第三刀：安全现实主义——拟态真实的精密制造（2008-2018）&quot;">​</a></h2><h3 id="_4-1-现实主义回归-的陷阱" tabindex="-1">4.1 &quot;现实主义回归&quot;的陷阱 <a class="header-anchor" href="#_4-1-现实主义回归-的陷阱" aria-label="Permalink to &quot;4.1 &quot;现实主义回归&quot;的陷阱&quot;">​</a></h3><p>2008年前后，一批&quot;现实主义&quot;作品获得巨大市场成功：《蜗居》《裸婚时代》《人民的名义》《我不是药神》。这常被解读为&quot;现实题材的复兴&quot;。</p><p>必须穿透这层表象。这些作品遵循一套极其严格的<strong>安全编码规则</strong>：</p><ul><li><strong>个体归因原则</strong>：所有问题最终归结为&quot;坏人&quot;或&quot;意外&quot;，绝不指向制度结构。《人民的名义》中，腐败是&quot;个别干部变质&quot;，而非权力监督机制的系统性缺失。</li><li><strong>清官叙事原则</strong>：解决困境的力量永远来自体制内部的&quot;好人&quot;（侯亮平、李达康），而非公民的集体行动。</li><li><strong>情感置换原则</strong>：用个体命运的悲情覆盖结构性追问。《我不是药神》让观众为程勇流泪，却成功地将&quot;医药体制为何如此&quot;这一制度之问，转化为&quot;好人为什么要受苦&quot;这一道德之问。</li></ul><p>这不是现实主义。这是<strong>经过安全处理的现实仿真</strong>。它的危险恰恰在于它&quot;看起来像现实&quot;。它给受众一种&quot;我在关注现实&quot;的幻觉，同时精确地切除了通往真正追问的那根神经。</p><h3 id="_4-2-类型片的全面架空" tabindex="-1">4.2 类型片的全面架空 <a class="header-anchor" href="#_4-2-类型片的全面架空" aria-label="Permalink to &quot;4.2 类型片的全面架空&quot;">​</a></h3><p>与此并行的是类型片的爆发式增长：仙侠（《花千骨》《三生三世》）、甜宠（《致我们单纯的小美好》）、宫斗（《甄嬛传》《延禧攻略》）、职场爽剧（《我的前半生》）。</p><p>这些作品的共同特征是<strong>时空绝缘</strong>：它们构建一个与现实中国完全脱钩的叙事容器。在其中，情感可以极端，冲突可以激烈，权力可以残酷——但这一切都发生在&quot;古代&quot;&quot;仙界&quot;&quot;平行时空&quot;中，与观众此刻此地的生存经验之间不存在任何映射关系。</p><p>这不是&quot;逃避现实&quot;。逃避是主体的主动选择。这里发生的是<strong>感知通道的系统性封堵</strong>。当一个人每天消费六小时&quot;架空叙事&quot;，他对&quot;此时此地&quot;的感知分辨率会不可逆地下降。他并非&quot;不愿面对现实&quot;，而是逐渐<strong>丧失了将经验识别为&quot;现实&quot;的认知图式</strong>。</p><h3 id="_4-3-算法作为审查的自动化延伸" tabindex="-1">4.3 算法作为审查的自动化延伸 <a class="header-anchor" href="#_4-3-算法作为审查的自动化延伸" aria-label="Permalink to &quot;4.3 算法作为审查的自动化延伸&quot;">​</a></h3><p>2012年后，推荐算法全面接管内容分发。这常被视为技术问题，但其政治后果远超技术范畴。</p><p>算法的本质是<strong>注意力经济的最优解</strong>：什么内容让用户停留时间最长，什么内容就获得最大分发。而&quot;安全内容&quot;天然具有分发优势——它不会引发不适，不会触发举报，不会招致下架。于是，算法在客观上完成了一项政治任务：<strong>将&quot;安全&quot;与&quot;可见&quot;绑定，将&quot;尖锐&quot;与&quot;消失&quot;绑定。</strong></p><p>这比任何人工审查都高效，因为它不需要审查者做出判断。系统自动运行。创作者甚至不需要知道红线在哪里，他只需要观察&quot;什么火了，什么没了&quot;，就能完成精确的自我校准。</p><p>福柯所说的&quot;全景敞视监狱&quot;在此获得了数字时代的终极形态：你甚至不知道看守在哪里，但你已经永远在自我规训。</p><h2 id="五、第四刀-痛觉的器质性丧失——从-不敢说-到-没感觉-2018至今" tabindex="-1">五、第四刀：痛觉的器质性丧失——从&quot;不敢说&quot;到&quot;没感觉&quot;（2018至今） <a class="header-anchor" href="#五、第四刀-痛觉的器质性丧失——从-不敢说-到-没感觉-2018至今" aria-label="Permalink to &quot;五、第四刀：痛觉的器质性丧失——从&quot;不敢说&quot;到&quot;没感觉&quot;（2018至今）&quot;">​</a></h2><h3 id="_5-1-审查的终极形态-消灭表达的需求" tabindex="-1">5.1 审查的终极形态：消灭表达的需求 <a class="header-anchor" href="#_5-1-审查的终极形态-消灭表达的需求" aria-label="Permalink to &quot;5.1 审查的终极形态：消灭表达的需求&quot;">​</a></h3><p>所有前述阶段的累积效应在2018年后呈现为一种质变。这一阶段的标志性特征不是&quot;更多作品被禁&quot;，而是<strong>需要被禁的作品越来越少</strong>。</p><p>因为创作者已经不再产生&quot;冒犯性&quot;的创作冲动。这不是恐惧的结果——恐惧至少意味着你仍然感知到了危险。这是一种更深的状态：<strong>感知本身的萎缩</strong>。当一个编剧在构思剧本时，他的大脑中已经不存在&quot;这个问题值得写&quot;的神经回路。不是他&quot;不敢写&quot;，是他的认知系统中根本没有生成这个选项的底层代码。</p><p>这才是&quot;无形之手&quot;最精妙的杰作。它不需要禁止你说话。它只需要让你忘记自己曾经有话要说。</p><h3 id="_5-2-受众侧的感知退化" tabindex="-1">5.2 受众侧的感知退化 <a class="header-anchor" href="#_5-2-受众侧的感知退化" aria-label="Permalink to &quot;5.2 受众侧的感知退化&quot;">​</a></h3><p>与之对应的是受众侧的变化。2020年代的中国观众面对一部&quot;深刻&quot;作品时，最常见的反应不是&quot;被震撼&quot;，而是&quot;好累&quot;&quot;太沉重了&quot;&quot;能不能轻松点&quot;。</p><p>这不是审美偏好的自然演变。这是四十年感知驯化的生理性后果。正如长期使用止痛剂的人会对正常疼痛产生过度反应一样，长期消费&quot;安全文艺&quot;的人，会对任何超出舒适区的真实表达产生本能的排斥。他们的感官系统已经适应了无菌环境，任何未经处理的现实都成了&quot;刺激物&quot;。</p><h3 id="_5-3-正能量-作为感知的最终格式化" tabindex="-1">5.3 &quot;正能量&quot;作为感知的最终格式化 <a class="header-anchor" href="#_5-3-正能量-作为感知的最终格式化" aria-label="Permalink to &quot;5.3 &quot;正能量&quot;作为感知的最终格式化&quot;">​</a></h3><p>2018年后全面推行的&quot;正能量&quot;话语体系，不应被简单理解为宣传口号。它在文艺领域执行的是一种<strong>感知的最终格式化</strong>：所有经验必须被编码为&quot;积极的&quot;&quot;向上的&quot;&quot;温暖的&quot;才能进入公共流通。</p><p>这意味着，苦难只有在被转化为&quot;励志叙事&quot;后才被允许存在；愤怒只有在被导向&quot;个别坏人&quot;后才被允许表达；追问只有在指向&quot;解决方案&quot;后才被允许发生。</p><p>文艺不再反映现实，不再追问现实，甚至不再&quot;美化&quot;现实。它<strong>替代</strong>现实。它提供一个完整的、自洽的、不需要外部验证的情感闭环。在这个闭环中，你不需要知道外面发生了什么，因为里面已经给了你所有你需要的情绪。</p><h2 id="六、解剖结论-那只手的骨骼结构" tabindex="-1">六、解剖结论：那只手的骨骼结构 <a class="header-anchor" href="#六、解剖结论-那只手的骨骼结构" aria-label="Permalink to &quot;六、解剖结论：那只手的骨骼结构&quot;">​</a></h2><p>综合四十年变迁，这只&quot;无形之手&quot;并非单一主体，而是一套<strong>多层次的协同系统</strong>：</p><p>层级机制功能第一层审查制度（剧本审查、上映许可、下架机制）设定外部边界第二层资本激励结构（投资回报、平台采购标准）将边界内化为创作本能第三层算法分发逻辑自动化地奖励&quot;安全&quot;、惩罚&quot;尖锐&quot;第四层受众感知适应消除对&quot;另一种文艺&quot;的需求第五层创作者的自我驯化消灭&quot;冒犯性表达&quot;的产生本身这五层构成一个完美的闭环。它不需要一个&quot;总指挥&quot;。它是一台自动运行的机器。每一个环节中的参与者——审查官、投资人、平台运营、算法工程师、创作者、观众——都只是在&quot;做自己的工作&quot;。没有人觉得自己在执行压制。但系统的总输出是确定的：<strong>公共痛感的系统性切除。</strong></p><p>这才是阿多诺在《启蒙辩证法》中预言的&quot;文化工业&quot;的最彻底实现。只不过，在阿多诺的论述中，文化工业服务于资本增殖；而在这里，资本增殖本身服务于一个更根本的目标：<strong>治理的稳定性。</strong> 资本不是主人，资本是工具。利润不是目的，利润是手段。</p><h2 id="七、终章-在无菌室里寻找痛觉" tabindex="-1">七、终章：在无菌室里寻找痛觉 <a class="header-anchor" href="#七、终章-在无菌室里寻找痛觉" aria-label="Permalink to &quot;七、终章：在无菌室里寻找痛觉&quot;">​</a></h2><p>写到这里，必须面对一个残酷的问题：如果感知已经器质性退化，复健是否可能？</p><p>诚实的回答是：极其困难，但并非不可能。因为人的感知系统有一个最后的堡垒——<strong>身体</strong>。你可以驯化一个人的认知框架，但你很难驯化他的身体反应。当一个人亲眼目睹不公时，他的胃会收缩；当一个人亲历荒诞时，他的太阳穴会跳动。这些前语言的、前叙事的身体反应，是任何文艺产品都无法完全覆盖的。</p><p>但身体反应需要被<strong>翻译</strong>为语言，才能成为公共表达。而翻译的工具——文学、电影、戏剧、音乐——恰恰是被系统性缴械的领域。</p><p>因此，真正的抵抗不在&quot;争取说话的权利&quot;——那已经是第二层的问题。真正的抵抗在第一层：<strong>重新学会感觉。</strong> 重新允许自己不适。重新拒绝被抚慰。重新在&quot;好累&quot;&quot;太沉重了&quot;的本能排斥面前停下来，问自己：我是真的累了，还是我被训练成了对真实过敏的人？</p><p>在一个感知被系统性地切除的时代，<strong>保持痛感就是保持人之为人的最低限度的证据。</strong></p><p>那只手可以切除你的声带，可以麻痹你的神经，可以给你的眼睛蒙上柔光滤镜。但它无法切除你身体深处那个在深夜突然醒来、感到有什么不对的瞬间。</p><p>那个瞬间，是一切重建的起点。</p><p>前提是，你还没有学会对那个瞬间也感到&quot;好累&quot;。</p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2076629995330466635" target="_blank" rel="noreferrer">查看原文</a>（2 赞）</p></blockquote>',67)])])}const g=o(r,[["render",e]]);export{d as __pageData,g as default};
